package com.tdc.nhom6.doanjava1.controller;
import com.tdc.nhom6.doanjava1.model.*;import com.tdc.nhom6.doanjava1.service.*;import javax.servlet.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.io.IOException;import java.util.*;
@Controller @RequestMapping("/books") public class BookController {
 private final BookService books;private final BorrowService borrows;public BookController(BookService b,BorrowService r){books=b;borrows=r;}
 @GetMapping public String list(@RequestParam(required=false)String keyword,@RequestParam(required=false)String category,@RequestParam(defaultValue="false")boolean availableOnly,HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");List<Book> list=keyword!=null&&!keyword.isBlank()?books.search(keyword):category!=null&&!category.isBlank()?books.findByCategory(category):availableOnly?books.findAvailable():books.findAll();m.addAttribute("account",a);m.addAttribute("books",list);m.addAttribute("keyword",keyword);m.addAttribute("selectedCat",category);m.addAttribute("availableOnly",availableOnly);m.addAttribute("borrowedIds",a==null?Collections.emptySet():borrows.findActiveBookIds(a.getId()));return "books/list";}
 @GetMapping("/{id}/cover") public void cover(@PathVariable Long id,@RequestParam(defaultValue="false")boolean download,HttpServletResponse res)throws IOException{Book b=books.findById(id);if(b==null||!b.isHasCover()){res.setStatus(404);return;}String type=b.getCoverType()==null?"image/jpeg":b.getCoverType();res.setContentType(type);res.setHeader("Content-Disposition",download?"attachment; filename=cover_"+id:"inline");res.getOutputStream().write(b.getCoverImage());}
 @GetMapping({"/add","/new"}) public String add(HttpSession s,Model m){if(!manager(s))return "redirect:/books";m.addAttribute("account",s.getAttribute("currentUser"));m.addAttribute("book",new Book());return "books/form";}
 @PostMapping("/add") public String addPost(@ModelAttribute Book b,HttpSession s,RedirectAttributes ra){if(!manager(s))return "redirect:/books";try{books.save(b);ra.addFlashAttribute("success","Đã thêm sách '"+b.getTitle()+"'!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/books";}
 @PostMapping public String create(@ModelAttribute Book b,HttpSession s,RedirectAttributes ra){return addPost(b,s,ra);}
 @GetMapping({"/edit/{id}","/{id}/edit"}) public String edit(@PathVariable Long id,HttpSession s,Model m){if(!manager(s))return "redirect:/books";Book b=books.findById(id);if(b==null)return "redirect:/books";m.addAttribute("account",s.getAttribute("currentUser"));m.addAttribute("book",b);return "books/form";}
 @PostMapping("/edit/{id}") public String editPost(@PathVariable Long id,@ModelAttribute Book b,HttpSession s,RedirectAttributes ra){if(!manager(s))return "redirect:/books";try{books.update(id,b);ra.addFlashAttribute("success","Đã cập nhật sách!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/books";}
 @PostMapping("/{id}") public String update(@PathVariable Long id,@ModelAttribute Book b,HttpSession s,RedirectAttributes ra){return editPost(id,b,s,ra);}
 @PostMapping("/{id}/cover") public String uploadCover(@PathVariable Long id,@RequestParam("file")MultipartFile f,HttpSession s,RedirectAttributes ra){if(!manager(s))return "redirect:/books";try{if(f.isEmpty()||f.getContentType()==null||!f.getContentType().startsWith("image/"))throw new IllegalArgumentException("Chỉ chấp nhận file ảnh");books.uploadCover(id,f);ra.addFlashAttribute("success","Đã cập nhật ảnh bìa!");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/books/edit/"+id;}
 @PostMapping({"/delete/{id}","/{id}/delete"}) public String delete(@PathVariable Long id,HttpSession s,RedirectAttributes ra){if(!manager(s))return "redirect:/books";try{books.delete(id);ra.addFlashAttribute("success","Đã xóa sách!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/books";}
 private boolean manager(HttpSession s){Account a=(Account)s.getAttribute("currentUser");return a!=null&&a.canManage();}
}